from decimal import Decimal, localcontext

from .money import MAX_AMOUNT, _exact_context, format_amount, parse_amount


def make_invoice(amounts):
    if not isinstance(amounts, (list, tuple)):
        raise ValueError("amounts must be a list")
    total = Decimal("0.00")
    with localcontext(_exact_context()):
        for item in amounts:
            # Running total stays <= MAX_AMOUNT, so each sum is exact.
            total += parse_amount(item)
            if total > MAX_AMOUNT:
                raise ValueError("invoice total exceeds maximum")
    return {"total": format_amount(total), "count": len(amounts)}

